                new BossAction(BossEvent.NativeDamageTaken,BossMechanism.Defense,BossPayload.Shield,"NyxMantle",cooldownMillis:BossNyxBalance.ArmorA0CooldownMillis,lifetimeMillis:BossNyxBalance.ArmorA0LifetimeMillis,maxInstances:BossNyxBalance.ArmorA0MaxInstances,element:BossElement.Light),
                NyxCircle(BossEvent.Clock,"NyxMantleBurst",BossNyxBalance.ArmorA1RadiusMilli,BossNyxBalance.ArmorA1DelayMillis)),
