                NyxCircle(BossEvent.Clock,"NyxStarsea",BossNyxBalance.Stage6A1RadiusMilli,BossNyxBalance.Stage6A1DelayMillis),
                new BossAction(BossEvent.Clock,BossMechanism.Defense,BossPayload.Shield,"NyxStarseaShield",delayMillis:BossNyxBalance.Stage6A2DelayMillis,lifetimeMillis:BossNyxBalance.Stage6A2LifetimeMillis,maxInstances:BossNyxBalance.Stage6A2MaxInstances,element:BossElement.Light)),
        };

        internal static BossRewardProfile[] CreateNyxRewards()
        {
            BossRewardAction Pull() => new BossRewardAction(BossRewardActionKind.NativeSpeed,count:BossNyxBalance.RewardPullCount,magnitudeMilli:BossNyxBalance.RewardPullMagnitudeMilli,speedMilli:BossNyxBalance.RewardPullSpeedMilli);
            BossRewardAction Radius() => new BossRewardAction(BossRewardActionKind.NativeState,rangeMilli:BossNyxBalance.RewardRadiusRangeMilli,order:1,magnitudeMilli:BossNyxBalance.RewardRadiusMagnitudeMilli);
            BossRewardAction End() => new BossRewardAction(BossRewardActionKind.NativeDamage,BossNyxBalance.RewardEndValueMilli,BossNyxBalance.RewardEndCapMilli,durationMillis:BossNyxBalance.RewardEndDurationMillis,count:BossNyxBalance.RewardEndCount,order:2,magnitudeMilli:BossNyxBalance.RewardEndMagnitudeMilli,rangeMilli:BossNyxBalance.RewardEndRangeMilli);
            return new[] { new BossRewardProfile(NyxRewardId,NyxSetId,"St_U_HerWorld",BossRewardAdapter.HerWorld,new[]
            {
                new BossRewardStage(1,new Txt("自身が装着している「彼女の世界（Her World）」の継続ダメージ領域内の通常敵に対し、毎秒1mの追加引き寄せ効果を付与する（1回の効果につき敵1体あたり追加移動2mまで。ボスと行動妨害が効かない敵は除外。元の挙動や持続時間は維持される）。", "Your equipped Her World pulls normal enemies inside its damage-over-time area an additional 1m per second, up to 2m of additional movement per enemy for each use. Does not affect bosses and enemies immune to crowd control. The skill's original behavior and duration are unchanged."),new[] { Pull() }),
                new BossRewardStage(2,new Txt("固有報酬の段階1の効果に加え、「彼女の世界」の継続ダメージ半径を上限8mまで最大1m拡張する。持続終了時または装備解除時に増加分のみ解除される（元の光属性継続ダメージやダメージ量は変化しない）。", "In addition to boss reward stage 1, increase Her World's damage-over-time radius by up to 1m, to a maximum of 8m. Only this increase is removed when the effect ends or you unequip it. Its original Light damage over time and damage amount are unchanged."),new[] { Pull(),Radius() }),
                new BossRewardStage(3,new Txt("固有報酬の段階2の効果に加え、継続ダメージが命中した敵を最大3体まで記録する。その効果が自然終了した際、記録された敵への追撃が命中すると、それぞれ1回のみ攻撃力・魔力の高い方の45%の光属性ダメージを追加で与える。また、元のスタン時間を上限3秒まで最大0.25秒延長する（死亡による中断や強制解除、部屋移動時は追加ダメージなし）。", "In addition to boss reward stage 2, remember up to 3 enemies hit by Her World's damage over time. When the effect ends naturally, its follow-up hit deals additional Light damage equal to 45% of whichever is higher: your Attack or Ability Power, once to each remembered enemy it hits. Also extend the original stun by up to 0.25 seconds, to a maximum of 3 seconds. No additional damage is dealt if the effect is interrupted by death, forcibly removed, or ended by changing rooms."),new[] { Pull(),Radius(),End() }),
            }) };
        }
